func CurrentLoginNameAndOrgs(client *Client, hostname string) (string, []string, error) {
	var query struct {
		Viewer struct {
			Login         string
			Organizations struct {
				Nodes []struct {
					Login string
				}
			} `graphql:"organizations(first: 100)"`
		}
	}
	err := client.Query(hostname, "UserCurrent", &query, nil)
	if err != nil {
		return "", nil, err
	}

	orgs := make([]string, 0, len(query.Viewer.Organizations.Nodes))
	for _, org := range query.Viewer.Organizations.Nodes {
		orgs = append(orgs, org.Login)
	}

	return query.Viewer.Login, orgs, nil
}

